// Worker entry (wrangler `main`). Wraps the OpenNext worker to add a
// scheduled() handler (QA F6): every 15 minutes it asks the app to cancel
// pending_payment orders past settings.orders.paymentWindowMinutes. The app
// route does the R2 work so it runs with the normal OpenNext context.
// Requires the CRON_SECRET secret; without it the route answers 404 and the
// lazy expiry on admin/tracking reads remains the only sweep.
// See https://opennext.js.org/cloudflare/howtos/custom-worker
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';
import { CACHE_HEADER, edgeTtl, isCacheableRequest } from './src/lib/edge-cache.ts';

// WS-J: Cache Rules never apply to a Worker on a custom domain, so public
// HTML (s-maxage) and immutable /media are cached here with the Cache API.
// Admin saves call purgeEdge() (src/lib/edge-purge.ts). Note caches.default
// is per data centre; the short HTML TTL bounds staleness elsewhere.
async function cachedFetch(request, env, ctx) {
  const cache = globalThis.caches && globalThis.caches.default;
  const ok =
    cache &&
    isCacheableRequest({
      method: request.method,
      url: request.url,
      cookie: request.headers.get('cookie'),
      rsc: request.headers.has('rsc') || request.headers.has('next-router-prefetch'),
    });
  if (!ok) return handler.fetch(request, env, ctx);

  const key = new Request(request.url, { method: 'GET' });
  const hit = await cache.match(key);
  if (hit) {
    const res = new Response(request.method === 'HEAD' ? null : hit.body, hit);
    const origin = hit.headers.get('x-nowhence-origin-cc');
    if (origin) res.headers.set('cache-control', origin);
    res.headers.delete('x-nowhence-origin-cc');
    res.headers.set(CACHE_HEADER, 'HIT');
    return res;
  }

  const res = await handler.fetch(request, env, ctx);
  const path = new URL(request.url).pathname;
  const ttl = edgeTtl(path, {
    status: res.status,
    cacheControl: res.headers.get('cache-control'),
    setCookie: res.headers.has('set-cookie'),
  });
  if (ttl == null || request.method !== 'GET') {
    const out = new Response(res.body, res);
    out.headers.set(CACHE_HEADER, 'BYPASS');
    return out;
  }
  const [a, b] = res.body ? res.body.tee() : [null, null];
  const stored = new Response(b, res);
  // Edge TTL only; browsers still get the origin cache-control.
  stored.headers.set('x-nowhence-origin-cc', res.headers.get('cache-control') || '');
  stored.headers.set('cache-control', `public, max-age=${ttl}`);
  ctx.waitUntil(cache.put(key, stored).catch((err) => console.error('edge cache put failed', err && err.message)));
  const out = new Response(a, res);
  out.headers.set(CACHE_HEADER, 'MISS');
  return out;
}

export default {
  fetch: cachedFetch,
  async scheduled(_event, env, ctx) {
    if (!env.CRON_SECRET) return;
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch('https://nowhenceclothings.com/api/admin/orders/expire', {
        method: 'POST',
        headers: { 'x-cron-secret': env.CRON_SECRET },
      }).then(
        async (r) => console.log('cron expire-orders', r.status, await r.text()),
        (err) => console.error('cron expire-orders failed', err && err.message),
      ),
    );
  },
};
